// Ajuste aqui. Roda uma vez por dia: pega até "limite" buscas sem resultado
// (buscadas 3 vezes ou mais) e pede ao modelo termos em inglês para cada uma.
// O site testa cada termo nos ícones e só guarda os que acham algo.
return [{
  json: {
    site: "https://iconlibrary.io",
    ollama: "http://ollama:11434",
    modelo: "gemma3:4b",
    limite: 20,
    // Vazio: não manda resumo no Telegram
    telegramChatId: "",
  },
}];

// Um item por termo; sem termos, o fluxo para aqui
const termos = $input.first().json.terms ?? [];
return termos.map((t) => ({ json: t }));

// O pedido ao modelo: só o termo e o idioma, nada sobre quem buscou
const config = $('Configuração').first().json;
const IDIOMAS = { en: 'English', es: 'Spanish', fr: 'French', de: 'German', ru: 'Russian', 'zh-CN': 'Simplified Chinese', 'pt-BR': 'Brazilian Portuguese', ja: 'Japanese' };
// hint: a nota do dono do site ao pedir uma nova análise no /admin
const { term, lang, hint } = $json;
const pedido = [
  'You help the search of an icon website. Icon names and keywords are in English,',
  'like the icons of Lucide and Bootstrap Icons: trash, shopping-cart, arrow-right, credit-card, bell.',
  'A visitor searched in ' + (IDIOMAS[lang] ?? 'English') + ' for: "' + term + '" and found no icon.',
  'List up to 6 English words or short names (1 to 3 words, lowercase) that an icon showing the same thing would be named or tagged with,',
  'most likely first. Prefer concrete objects and common icon names. Translate first if the term is not English.',
  'If the term is a person\'s name, a brand, a typo you cannot fix, offensive, or personal data, return an empty list.',
  hint ? 'A previous answer was wrong. The site owner says: "' + hint + '". Follow this note.' : '',
].filter(Boolean).join(' ');
return {
  json: {
    corpo: {
      model: config.modelo,
      stream: false,
      keep_alive: '2m',
      options: { temperature: 0, num_ctx: 2048 },
      format: { type: 'object', properties: { candidatos: { type: 'array', items: { type: 'string' } } }, required: ['candidatos'] },
      messages: [{ role: 'user', content: pedido }],
    },
  },
};

// A resposta do modelo vira o pedido ao site. JSON quebrado: lista vazia
// (o site marca o termo como tentado e ele volta em 30 dias)
const termo = $('Separar').item.json;
let candidatos = [];
try {
  candidatos = JSON.parse($json.message?.content ?? '{}').candidatos ?? [];
} catch {}
return { json: { term: termo.term, lang: termo.lang, candidates: candidatos.filter((c) => typeof c === 'string').slice(0, 8) } };

// Uma mensagem com o que entrou na busca hoje
const linhas = [];
for (const [i, item] of $input.all().entries()) {
  const pedido = $('Montar pedido').all()[i]?.json ?? {};
  const aprendidos = item.json.learned ?? [];
  if (aprendidos.length) linhas.push('✅ ' + pedido.term + ' (' + pedido.lang + ') → ' + aprendidos.join(', '));
  else if (item.json.error) linhas.push('⚠️ ' + pedido.term + ': ' + JSON.stringify(item.json.error).slice(0, 80));
  else linhas.push('— ' + pedido.term + ' (' + pedido.lang + '): nada achou');
}
const config = $('Configuração').first().json;
return [{ json: { chatId: config.telegramChatId, texto: '🔎 Busca que aprende — ' + linhas.length + ' termo(s)\n' + linhas.join('\n') + '\n\nExcluir um ruim: /admin → Buscas sem resultado → Sinônimos aprendidos' } }];
